# Unabhängige Löser für alle Textaufgaben-Vorlagen (eigene Rechnung aus dem Aufgabentext, exakte Brüche)
import re
from fractions import Fraction as F
from math import comb
NAMES = 'Lena|Tim|Mia|Ben|Emma|Noah|Sofia|Elias|Hannah|Luca|Mila|Paul|Ella|Finn|Leonie|Jonas|Aylin|Mats|Zoe|Can'
MON = {'März': 31, 'April': 30, 'Mai': 31, 'Juni': 30, 'Juli': 31, 'Oktober': 31, 'November': 30, 'Dezember': 31}
NUM = r'(\d+(?:\.\d{3})*(?:,\d+)?|\d+:\d\d)'
def val(s):
    if ':' in s: h, m = s.split(':'); return F(int(h) * 60 + int(m))
    return F(s.replace('.', '').replace(',', '.'))
def rx(tpl):
    p = re.sub(r'\bN\b', '(?:' + NAMES + ')', re.escape(tpl).replace('\\#', NUM))
    return re.compile('^' + p + '$')
S = []
def st(tpl):
    def deco(fn): S.append((rx(tpl), fn)); return fn
    return deco
# ---------- Prozent (Profi) ----------
st('Ein Preis von # € steigt erst um # % und sinkt dann um # %. Wie hoch ist er am Ende?')(lambda b, p, q: b * (1 + p / 100) * (1 - q / 100))
st('Nach einer Erhöhung um # % kostet etwas # €. Was hat es vorher gekostet?')(lambda p, x: x / (1 + p / 100))
st('Nach # % Rabatt kostet etwas # €. Was hat es vorher gekostet?')(lambda p, x: x / (1 - p / 100))
