st('Von # Uhr bis # Uhr: Wie viele Minuten sind das?')(lambda a, b: b - a)
def _days(a, m1, b, m2):
    order = list(MON); i, j = order.index(m1), order.index(m2)
    nxt = {'März': 'April', 'April': 'Mai', 'Mai': 'Juni', 'Juni': 'Juli', 'Oktober': 'November', 'November': 'Dezember'}
    assert nxt[m1] == m2, 'Monate nicht aufeinander'
    return MON[m1] - a + b
S.append((re.compile('^Heute ist der ' + NUM + r'\. (März|April|Mai|Juni|Juli|Oktober|November|Dezember)\. In wie vielen Tagen ist der ' + NUM + r'\. (März|April|Mai|Juni|Juli|Oktober|November|Dezember)\?$'), lambda a, m1, b, m2: _days(a, m1, b, m2)))
st('Ein Film beginnt um # Uhr und dauert # Minuten. Wie viele Minuten nach # Uhr ist er zu Ende?')(lambda s, d, h: s + d - h * 60 if (s + d) // 60 == h else None)
