def _sq(x):
    r = int(round(float(x) ** .5)); assert r * r == x, 'keine ganze Wurzel'; return F(r)
st('Ein rechtwinkliges Dreieck hat die Katheten # cm und # cm. Wie lang ist die Hypotenuse?')(lambda a, b: _sq(a * a + b * b))
