st('# € liegen # Tage zu # % Jahreszins auf dem Konto (# Jahr = # Tage). Wie viele Euro Zinsen gibt es?')(lambda k, t, p, one, y: k * p / 100 * t / y)
st('# € bringen in # Monaten # € Zinsen. Wie hoch ist der Jahreszinssatz?')(lambda k, m, z: z / m * 12 * 100 / k)
st('# € werden # Jahre lang mit # % verzinst, die Zinsen bleiben auf dem Konto. Wie viel Geld ist es nach # Jahren?')(lambda k, n, p, n2: k * (1 + p / 100) ** int(n))
# ---------- Statistik ----------
S.append((re.compile(r'^Der Durchschnitt von (\d+) Zahlen ist (\d+)\. (\d+) davon sind ([\d, ]+)\. Wie heißt die fehlende Zahl\?$'), lambda n, m, k, lst: n * m - sum(F(x) for x in lst.split(', '))))
st('Klasse A hat # Kinder mit durchschnittlich # Punkten, Klasse B # Kinder mit durchschnittlich # Punkten und Klasse C # Kinder mit durchschnittlich # Punkten. Wie groß ist der Durchschnitt aller Kinder?')(lambda a, ma, b, mb, c, mc: (a * ma + b * mb + c * mc) / (a + b + c))
# ---------- Kreis (π = 3,14, wie angegeben) ----------
PI = F(314, 100)
st('Ein Kreis hat den Durchmesser # cm. Wie groß ist sein Umfang?')(lambda d: PI * d)
st('Ein Kreis hat den Radius # cm. Wie groß ist sein Umfang?')(lambda r: 2 * PI * r)
st('Ein Kreis hat den Radius # cm. Wie groß ist seine Fläche?')(lambda r: PI * r * r)
st('Ein Kreis hat den Durchmesser # m. Wie groß ist seine Fläche?')(lambda d: PI * (d / 2) ** 2)
st('Ein Zylinder hat den Radius # cm und die Höhe # cm. Wie groß ist sein Volumen?')(lambda r, h: PI * r * r * h)
st('Ein Kreisring hat den Außenradius # cm und den Innenradius # cm. Wie groß ist seine Fläche?')(lambda R, r: PI * (R * R - r * r))
st('Ein Halbkreis hat den Durchmesser # m. Wie lang ist sein Rand (Bogen und Durchmesser)?')(lambda d: PI * d / 2 + d)
st('Ein Zylinder hat den Radius # cm und die Höhe # cm. Wie groß ist seine Oberfläche?')(lambda r, h: 2 * PI * r * r + 2 * PI * r * h)
# ---------- Dreisatz ----------
st('# Hefte kosten # €. Wie viel kosten # Hefte?')(lambda a, p, b: p / a * b)
st('Ein Auto fährt mit # Litern Benzin # km. Wie weit kommt es mit # Litern?')(lambda a, d, b: d / a * b)
st('# Pumpen leeren ein Becken in # Stunden. Wie lange brauchen # Pumpen?')(lambda p, t, q: p * t / q)
st('# kg Äpfel kosten # €. Wie viel kosten # kg?')(lambda a, p, b: p / a * b)
st('Ein Futtervorrat reicht für # Pferde # Tage. Nach # Tagen werden # Pferde verkauft. Wie viele Tage reicht der Rest?')(lambda k, d, t, z: k * (d - t) / (k - z))
st('Ein Futtervorrat reicht für # Pferde # Tage. Nach # Tagen werden # Pferde dazugekauft. Wie viele Tage reicht der Rest?')(lambda k, d, t, z: k * (d - t) / (k + z))
st('# Maschinen stellen in # Stunden # Teile her. Wie viele Teile stellen # Maschinen in # Stunden her?')(lambda m1, h1, n, m2, h2: n / (m1 * h1) * m2 * h2)
st('# Arbeiter pflastern einen Platz in # Tagen. Wie viele Tage brauchen # Arbeiter für # gleich große Plätze?')(lambda a, t, b, f: a * t * f / b)

def solve_story(text):
    for r, fn in S:
        m = r.match(text)
        if m:
            args = [g if g in MON or ', ' in g else val(g) for g in m.groups()]
            return fn(*args), True
    return None, False
